class Messenger(object):
    def __init__(self, subject, receivers, cc=None, files=None, sender='scperf.5g@nokia.com'):
        """
        Messenger class init method.
        :param subject: subject of the message as string
        :param receivers: list of "to" addresses or user IDs
        :param files: names of files you want to attach to message as list
        :param sender: address "from"
        """
        self.subject = subject
        self.receivers = receivers
        self.cc = cc
        self.files = files
        self.sender = sender

    def prepare_message(self, html_msg_content=None, text_msg_content=None):
        """
        Prepares message using values of class attributes.
        :param html_msg_content: message content in html format
        :param text_msg_content: message content in text format
        :return: Message object
        """
        receivers = set()
        if self.receivers:
            for receiver in self.receivers:
                if re.search(r"@[\w-]+(\.[\w-]+)*", receiver, re.I):
                    receivers.add(receiver)
                    continue
                else:
                    try:
                        mail = LDAP.get_user_email(user_id=receiver)
                        receivers.add(mail)
                    except ValueError:
                        log_info_to_console("User not found in LDAP: {}".format(receiver))
                        continue

        message = Message(From=self.sender, To=receivers, CC=self.cc, Subject=self.subject, Html=html_msg_content,
                          Body=text_msg_content, attachments=self.files, charset="utf-8")
        return message

    @staticmethod
    def send_message(message):
        """
        Sends message.
        :param message: Message object
        :return: nothing
        """

        server = smtplib.SMTP(host='mailrelay.int.nokia.com', port=25)
        if isinstance(message, Message):
            message = [message]

        for msg in message:
            to = [msg.To] if isinstance(msg.To, string_types) else msg.To
            if msg.CC:
                cc = [msg.CC] if isinstance(msg.CC, string_types) else msg.CC
                to = to + cc

            server.sendmail(from_addr=msg.From,
                            to_addrs=to,
                            msg=msg.as_string())

        server.quit()

    @staticmethod
    def generate_html_message_content(test_case, user_id, setup_name, setup_owner=None, build=None, release=None,
                                      time=None, jenkins_job_link=None, user_message=None):
        """
        Generates html message content using a template.
        :param test_case: test case name
        :param user_id: login to user account
        :param setup_name: name of setup
        :param setup_owner: owner/owners of setup
        :param build: build number
        :param release: release
        :param time:
        :param jenkins_job_link:
        :param user_message:
        :return: html message as string
        """
        tester_id = None
        tester = None
        if not setup_owner:
            setup_owner = "NOT SPECIFIED"
        else:
            try:
                tester_id = user_id
                tester = LDAP.get_user_fullname(user_id=user_id)
            except ValueError:
                tester_id = -1
                tester = "NOT SPECIFIED"
        html_message_template = Messenger.build_html_message_template()
        html_message_content = html_message_template.format(setup_name, test_case, build, release, setup_owner,
                                                            tester, tester_id, time, jenkins_job_link, user_message)
        return html_message_content

    @staticmethod
    def build_html_message_template():
        html_message_template = """
        <html>
        <head>
        </head>
          <body>
            <h3>Setup {} information</h3>
            <p>
               Test Case: {}<br>
               eNB build: {}<br>
               Release: {}<br>
               Setup owners: {}<br>
               Tester: {} ({})<br>
               Time: {}<br>
               <a href="{}">Jenkins job</a><br>
            </p>
            <p>{}</p>
          </body>
        </html>"""

        return html_message_template


class Message(object):
    """
    Represents an email message.

    Set the To, From, Reply-To, Subject, and Body attributes as plain-text strings.
    Optionally, set the Html attribute to send an HTML email, or use the
    attach() method to attach files.

    Use the charset property to send messages using other than us-ascii

    If you specify an attachments argument, it should be a list of
    attachment filenames: ["file1.txt", "file2.txt"]

    `To` should be a string for a single address, and a sequence
    of strings for multiple recipients (castable to list)

    Send using the Mailer class.
    """

    def __init__(self, **kwargs):
        """
        ***  Copy from mailer.py  ***
        Parameters and default values (parameter names are case insensitive):
            To=None, From=None, RTo=None, CC=None, BCC=None, Subject=None, Body=None, Html=None,
            Date=None, Attachments=None, Charset=None, Headers=None
        """

        # extract  parameters and convert names to lowercase
        params = {}
        for i in kwargs:
            params[i.lower()] = kwargs[i]

        self.To = params.get('to', None)
        self.CC = params.get('cc', None)
        self.From = params.get('from', None)
        self.Subject = params.get('subject', u'')
        self.Body = params.get('body', None)
        self.Html = params.get('html', None)
        self.Date = params.get('date', time.strftime("%a, %d %b %Y %H:%M:%S %z", time.gmtime()))
        self.charset = params.get('charset', 'us-ascii')
        self.attachments = self._preprocess_attachments(params.get('attachments', None))

        if hasattr(self.Body, 'encode'):
            self.Body = self.Body.encode(self.charset)

    def as_string(self):
        """Get the email as a string to send in the mailer"""

        if not self.attachments:
            return self._plaintext()
        else:
            return self._multipart()

    def _plaintext(self):
        """Plain text email with no attachments"""

        if not self.Html:
            msg = MIMEText(self.Body, 'plain', self.charset)
        else:
            msg = self._with_html()

        self._set_info(msg)
        return msg.as_string()

    def _with_html(self):
        """There's an html part"""

        outer = MIMEMultipart('alternative')

        part1 = MIMEText(self.Body, 'plain', self.charset)
        part2 = MIMEText(self.Html, 'html', self.charset)

        outer.attach(part1)
        outer.attach(part2)

        return outer

    def _set_info(self, msg):
        self.prepare_subject_and_from_header(msg)
        self.prepare_to_header(msg)
        self.prepare_cc_header(msg)
        msg['Date'] = self.Date

    def prepare_cc_header(self, msg):
        if self.CC:
            if isinstance(self.CC, string_types):
                msg['CC'] = self.CC
            else:
                self.CC = list(self.CC)
                msg['CC'] = ", ".join(self.CC)

    def prepare_to_header(self, msg):
        if isinstance(self.To, string_types):
            msg['To'] = self.To
        else:
            self.To = list(self.To)
            self.To = set(self.To)
            msg['To'] = ", ".join(self.To)

    def prepare_subject_and_from_header(self, msg):
        if self.charset == 'us-ascii':
            msg['Subject'] = self.Subject
            msg['From'] = self.From

        else:
            if hasattr(self.Subject, 'decode'):
                subject = self.Subject.decode(self.charset)
            else:
                subject = self.Subject

            msg['Subject'] = str(make_header([(subject, self.charset)]))  # tu jest konwer do str

            if hasattr(self.From, 'decode'):
                from_ = self.From.decode(self.charset)
            else:
                from_ = self.From

            msg['From'] = str(make_header([(from_, self.charset)]))

    def _multipart(self):
        """The email has attachments"""

        msg = MIMEMultipart('related')

        if self.Html:
            outer = MIMEMultipart('alternative')

            part1 = MIMEText(self.Body, 'plain', self.charset)
            part1.add_header('Content-Disposition', 'inline')

            part2 = MIMEText(self.Html, 'html', self.charset)
            part2.add_header('Content-Disposition', 'inline')

            outer.attach(part1)
            outer.attach(part2)
            msg.attach(outer)
        else:
            msg.attach(MIMEText(self.Body, 'plain', self.charset))

        self._set_info(msg)
        msg.preamble = self.Subject

        for filename, cid, mimetype, content, charset in self.attachments:
            self._add_attachment(msg, filename, cid, mimetype, content, charset)

        return msg.as_string()

    @staticmethod
    def _add_attachment(outer, filename, cid, mimetype, content, charset):
        """
        If mimetype is None, it will try to guess the mimetype
        """
        if mimetype:
            ctype = mimetype
            encoding = None
        else:
            ctype, encoding = mimetypes.guess_type(filename)

        if ctype is None or encoding is not None:
            # No guess could be made, or the file is encoded (compressed), so
            # use a generic bag-of-bits type.
            ctype = 'application/octet-stream'

        maintype, subtype = ctype.split('/', 1)
        if not content:
            with open(filename, 'rb') as fp:
                content = fp.read()

        types = {'text': MIMEText(content, _subtype=subtype, _charset=charset),
                 'image': MIMEImage(content, _subtype=subtype),
                 'audio': MIMEAudio(content, _subtype=subtype)}
        try:
            msg = types[maintype]
        except KeyError:
            msg = MIMEBase(maintype, subtype)
            msg.set_payload(content)
            # Encode the payload using Base64
            encoders.encode_base64(msg)

        # Set the content-ID header
        if cid:
            msg.add_header('Content-ID', '<%s>' % cid)
            msg.add_header('Content-Disposition', 'inline')
        else:
            # Set the filename parameter
            msg.add_header('Content-Disposition', 'attachment', filename=path.basename(filename))

        outer.attach(msg)

    def attach(self, filename, cid=None, mimetype=None, content=None, charset=None):
        """
        Attach a file to the email. Specify the name of the file;
        Message will figure out the MIME type and load the file.

        Specify mimetype to set the MIME type manually. The content
        argument take the contents of the file if they are already loaded
        in memory.
        """

        self.attachments.append((filename, cid, mimetype, content, charset))

    @staticmethod
    def _preprocess_attachments(attachments):
        _attachments = []
        if attachments:
            for attachment in attachments:
                Message.prepare_attachment(_attachments, attachment)
        return _attachments

    @staticmethod
    def prepare_attachment(_attachments, attachment):
        if isinstance(attachment, string_types):
            _attachments.append((attachment, None, None, None, None))
        else:
            try:
                length = len(attachment)
            except TypeError:
                length = None
            else:
                if length is None or length <= 4:
                    _attachments.append((attachment, None, None, None, None))
                else:
                    _attachments.append((tuple(attachment) + (None, None, None, None))[:4])


class LDAP(object):
    def __init__(self, user_id, ldap_address='ldap://ed-p-gl.emea.nsn-net.net'):
        """
        LDAP class init method
        :param user_id: login to user account
        """
        self.user_id = user_id
        self.ldap_address = ldap_address

    def get_attribute_from_ldap(self, attributes=None):
        """
        Gets values of given attributes.
        :param attributes: codes of attributes you want to get using LDAP
        :return: attributes as a dict
        """
        server = ldap3.Server(self.ldap_address, get_info=True)
        with ldap3.Connection(server, auto_bind=True) as conn:
            result = conn.search('ou=people,o=NSN', '(uid=' + self.user_id + ')', attributes=attributes)
            if result is False:
                raise ValueError("No entry for this user id: {}".format(self.user_id))
            result_in_json = json.loads(conn.entries[0].entry_to_json())
            return result_in_json["attributes"]

    @classmethod
    def get_user_fullname(cls, user_id):
        ldap_obj = cls(user_id=user_id)
        cn_attribute = ldap_obj.get_attribute_from_ldap(attributes=["cn"])
        full_name = cn_attribute["cn"][0]

        return full_name

    @classmethod
    def get_user_email(cls, user_id):
        ldap_obj = cls(user_id=user_id)
        mail_attribute = ldap_obj.get_attribute_from_ldap(attributes=['mail'])
        mail = mail_attribute["mail"][0]

        return mail
